package com.devforge.database;
import com.devforge.model.Snippet;import java.nio.file.*;import java.sql.*;import java.time.Instant;import java.util.*;
public final class Database {
 private final String url;
 public Database(){this(defaultPath());}
 private static Path defaultPath(){String local=System.getenv("LOCALAPPDATA");return local==null||local.isBlank()?Path.of(System.getProperty("user.home"),".local","share","DevForge","devforge.db"):Path.of(local,"DevForge","devforge.db");}
 public Database(Path path){try{Files.createDirectories(path.toAbsolutePath().getParent());}catch(Exception e){throw new IllegalStateException("Cannot create DevForge data directory",e);}url="jdbc:sqlite:"+path.toAbsolutePath();init();}
 public synchronized Connection connect()throws SQLException{return DriverManager.getConnection(url);}
 private void init(){try(Connection c=connect();Statement s=c.createStatement()){s.executeUpdate("CREATE TABLE IF NOT EXISTS snippets(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT,language TEXT,code TEXT,category TEXT,tags TEXT,favorite INTEGER,created TEXT,updated TEXT)");s.executeUpdate("CREATE INDEX IF NOT EXISTS idx_snippet_title ON snippets(title)");s.executeUpdate("CREATE TABLE IF NOT EXISTS history(id INTEGER PRIMARY KEY AUTOINCREMENT,at TEXT NOT NULL,description TEXT NOT NULL)");s.executeUpdate("CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL)");}catch(SQLException e){throw new IllegalStateException("Could not initialize local database",e);}}
 public synchronized List<Snippet> snippets(String search,String lang,String cat,String sort)throws SQLException{String order=switch(sort){case "Title"->"title COLLATE NOCASE";case "Created"->"created DESC";default->"updated DESC";};String q="SELECT * FROM snippets WHERE (?='' OR lower(title||' '||description||' '||tags||' '||code) LIKE ?) AND (?='All' OR language=?) AND (?='All' OR category=?) ORDER BY "+order;try(Connection c=connect();PreparedStatement p=c.prepareStatement(q)){String term="%"+search.toLowerCase()+"%";p.setString(1,search);p.setString(2,term);p.setString(3,lang);p.setString(4,lang);p.setString(5,cat);p.setString(6,cat);try(ResultSet r=p.executeQuery()){List<Snippet> out=new ArrayList<>();while(r.next())out.add(read(r));return out;}}}
 private Snippet read(ResultSet r)throws SQLException{return new Snippet(r.getString("id"),r.getString("title"),r.getString("description"),r.getString("language"),r.getString("code"),r.getString("category"),r.getString("tags"),r.getInt("favorite")!=0,Instant.parse(r.getString("created")),Instant.parse(r.getString("updated")));}
 public synchronized void save(Snippet x)throws SQLException{try(Connection c=connect();PreparedStatement p=c.prepareStatement("INSERT INTO snippets VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET title=excluded.title,description=excluded.description,language=excluded.language,code=excluded.code,category=excluded.category,tags=excluded.tags,favorite=excluded.favorite,updated=excluded.updated")){int i=1;p.setString(i++,x.id());p.setString(i++,x.title());p.setString(i++,x.description());p.setString(i++,x.language());p.setString(i++,x.code());p.setString(i++,x.category());p.setString(i++,x.tags());p.setInt(i++,x.favorite()?1:0);p.setString(i++,x.createdAt().toString());p.setString(i,x.updatedAt().toString());p.executeUpdate();}}
 public synchronized void delete(String id)throws SQLException{try(Connection c=connect();PreparedStatement p=c.prepareStatement("DELETE FROM snippets WHERE id=?")){p.setString(1,id);p.executeUpdate();}}
 public synchronized int count(String where)throws SQLException{try(Connection c=connect();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT count(*) FROM snippets"+where)){r.next();return r.getInt(1);}}
 public synchronized void activity(String text)throws SQLException{try(Connection c=connect();PreparedStatement p=c.prepareStatement("INSERT INTO history(at,description) VALUES(?,?)")){p.setString(1,Instant.now().toString());p.setString(2,text);p.executeUpdate();}}
 public synchronized List<String> history()throws SQLException{try(Connection c=connect();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT at||'  ·  '||description FROM history ORDER BY id DESC LIMIT 100")){List<String> a=new ArrayList<>();while(r.next())a.add(r.getString(1));return a;}}
 public synchronized void clearHistory()throws SQLException{try(Connection c=connect();Statement s=c.createStatement()){s.executeUpdate("DELETE FROM history");}}
 public synchronized String setting(String key,String fallback)throws SQLException{try(Connection c=connect();PreparedStatement p=c.prepareStatement("SELECT value FROM settings WHERE key=?")){p.setString(1,key);try(ResultSet r=p.executeQuery()){return r.next()?r.getString(1):fallback;}}}
 public synchronized void setSetting(String key,String value)throws SQLException{try(Connection c=connect();PreparedStatement p=c.prepareStatement("INSERT INTO settings VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value")){p.setString(1,key);p.setString(2,value);p.executeUpdate();}}
}
